import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "../index.css";

const DOMAINS = [
  "Healthcare",
  "Information Technology",
  "Software",
  "SaaS",
  "Finance",
  "Education",
  "E-commerce",
  "Marketing",
  "Manufacturing",
  "Retail",
  "Hospitality",
  "Transportation",
  "Telecommunications",
  "Real Estate",
  "Energy",
  "Energy & Utilities",
  "Automotive",
  "Agriculture",
  "Pharmaceuticals",
  "Media",
  "Media & Entertainment",
  "Entertainment",
  "Government",
  "Non-profit",
  "Legal",
  "Other",
  "Research & Development",
  "Cloud Computing",
  "Software Development",
  "Data Science",
  "Automation",
  "Web Development",
  "Mobile Apps",
  "AI & ML",
  "AI",
  "Cybersecurity"
];

const EXPERIENCE_LEVELS = ["beginner", "intermediate", "expert"];
const GENDERS = ["male", "female"];
const WORK_PREFERENCE = ["remote", "on-site", "hybrid"];
const AVAILABILITIES = ["full-time", "part-time", "freelance", "not available"];

const FreelancerForm = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    full_name: "",
    gender: "",
    country: "",
    city: "",
    date_of_birth: "",
    email: "",
    phone_number: "",
    linkedin_url: "",
    degree: "",
    graduation_year: "",
    experience_year: "",
    experience_level: "",
    professional_summary: "",
    certifications: "",
    portfolio: "",
    skills: "",
    domain: "",
    work_preference: "",
    availability: "",
    hourly_rate: "",
    project_name: [],
    resume_file: null,  
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const API_BASE = "http://127.0.0.1:8000";

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "resume_file") {
      setFormData({ ...formData, [name]: files[0] });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

    // Get user_id from localStorage
    const currentUser = JSON.parse(localStorage.getItem("currentUser") || "{}");
    const user_id = currentUser.user_id;
    if (!user_id) {
      setError("User not found. Please log in again.");
      setLoading(false);
      return;
    }

    // Validate file type
    if (formData.resume_file && !["text/plain", "application/pdf"].includes(formData.resume_file.type)) {
      setError("Resume must be a .txt or .pdf file.");
      setLoading(false);
      return;
    }

  // Handle project changes
    const handleProjectChange = (index, field, value) => {
      const updatedProjects = [...formData.projects];
      updatedProjects[index][field] = value;
      setFormData({ ...formData, projects: updatedProjects });
    };
    // Add a new project
    const addProject = () => {
      setFormData({
        ...formData,
        projects: [...formData.projects, { project_name: "", description: "" }],
      });
    };
    // Remove a project
    const removeProject = (index) => {
      const updatedProjects = formData.projects.filter((_, i) => i !== index);
      setFormData({ ...formData, projects: updatedProjects });
    };


  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError("");
    const dataToSend = new FormData();
    dataToSend.append("user_id", user_id);
    dataToSend.append("full_name", formData.full_name);
    dataToSend.append("gender", formData.gender);
    dataToSend.append("country", formData.country);
    dataToSend.append("city", formData.city);
    dataToSend.append("date_of_birth", formData.date_of_birth);
    dataToSend.append("email", formData.email);
    dataToSend.append("phone_number", formData.phone_number);
    dataToSend.append("linkedin_url", formData.linkedin_url);
    dataToSend.append("degree", formData.degree);
    dataToSend.append("graduation_year", formData.graduation_year ? parseInt(formData.graduation_year) : "");
    dataToSend.append("experience_year", formData.experience_year ? parseInt(formData.experience_year) : "");
    dataToSend.append("experience_level", formData.experience_level);
    dataToSend.append("professional_summary", formData.professional_summary);
    dataToSend.append("certifications", formData.certifications);
    dataToSend.append("portfolio", formData.portfolio);
    dataToSend.append("skills", formData.skills);
    dataToSend.append("domain", formData.domain);
    dataToSend.append("work_preference", formData.work_preference);
    dataToSend.append("availability", formData.availability);
    dataToSend.append("hourly_rate", formData.hourly_rate ? parseFloat(formData.hourly_rate) : "");
    dataToSend.append("projects", JSON.stringify(projects));
    if (formData.resume_file) {
      dataToSend.append("resume_file", formData.resume_file);
    }

    try {
      const response = await axios.post(`${API_BASE}/create-freelancer-profile`, dataToSend, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      alert("Freelancer profile created successfully!");
      navigate("/dashboard");
    } catch (err) {
      const msg = err.response?.data?.detail || "Failed to create profile.";
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="form-container">
      <h1 className="heading">SoftScale</h1>
      <div className="form-box">
        <h2>Freelancer Profile</h2>
        {error && <div style={{ color: "#cc3b3b", marginBottom: 12 }}>{error}</div>}
        <form onSubmit={handleSubmit}>
          <input
            name="full_name"
            placeholder="Full Name"
            value={formData.full_name}
            onChange={handleChange}
            required
          />
          <select
            name="gender"
            value={formData.gender}
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", background: "#fff" }}
            required
          >
            <option value="">Select Gender</option>
            {GENDERS.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
          <input
            name="country"
            placeholder="Country"
            value={formData.country}
            onChange={handleChange}
          />
          <input
            name="city"
            placeholder="City"
            value={formData.city}
            onChange={handleChange}
          />
          <input
            name="date_of_birth"
            type="date"
            placeholder="Date of Birth"
            value={formData.date_of_birth}
            onChange={handleChange}
          />
          <input
            name="email"
            type="email"
            placeholder="Email"
            value={formData.email}
            onChange={handleChange}
            required
          />
          <input
            name="phone_number"
            placeholder="Phone Number"
            value={formData.phone_number}
            onChange={handleChange}
            required
          />
          <input
            name="linkedin_url"
            placeholder="LinkedIn URL"
            value={formData.linkedin_url}
            onChange={handleChange}
          />
          <input
            name="degree"
            placeholder="Degree"
            value={formData.degree}
            onChange={handleChange}
          />
          <input
            name="graduation_year"
            type="number"
            placeholder="Graduation Year"
            value={formData.graduation_year}
            onChange={handleChange}
          />
          <input
            name="experience_year"
            type="number"
            placeholder="Experience (years)"
            value={formData.experience_year}
            onChange={handleChange}
          />
          <select
            name="experience_level"
            value={formData.experience_level}
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", background: "#fff" }}
            required
          >
            <option value="">Select Experience Level</option>
            {EXPERIENCE_LEVELS.map((level) => (
              <option key={level} value={level}>
                {level}
              </option>
            ))}
          </select>
          <textarea
            name="professional_summary"
            placeholder="Professional Summary"
            value={formData.professional_summary}
            onChange={handleChange}
            rows={4}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />
          <textarea
            name="certifications"
            placeholder="Certifications"
            value={formData.certifications}
            onChange={handleChange}
            rows={3}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />
          <textarea
            name="portfolio"
            placeholder="Portfolio"
            value={formData.portfolio}
            onChange={handleChange}
            rows={3}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />
          <textarea
            name="skills"
            placeholder="Skills (comma separated)"
            value={formData.skills}
            onChange={handleChange}
            rows={3}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />
          <label style={{ display: "block", marginTop: 8, marginBottom: 6, color: "#333", fontSize: 14 }}>
            Domain
          </label>
          <select
            name="domain"
            value={formData.domain}
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", background: "#fff" }}
            required
          >
            <option value="">Select Domain</option>
            {DOMAINS.map((d) => (
              <option key={d} value={d}>
                {d}
              </option>
            ))}
          </select>
          <select
            name="work_preference"
            value={formData.work_preference}
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", background: "#fff" }}
            required
          >
            <option value="">Select Work Preference</option>
            {WORK_PREFERENCE.map((pref) => (
              <option key={pref} value={pref}>
                {pref}
              </option>
            ))}
          </select>
          <select
            name="availability"
            value={formData.availability}
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", background: "#fff" }}
            required
          >
            <option value="">Select Availability</option>
            {AVAILABILITIES.map((avail) => (
              <option key={avail} value={avail}>
                {avail}
              </option>
            ))}
          </select>
          <input
            name="hourly_rate"
            type="number"
            step="0.01"
            placeholder="Hourly Rate ($)"
            value={formData.hourly_rate}
            onChange={handleChange}
          />
          <label style={{ display: "block", marginTop: 8, marginBottom: 6, color: "#333", fontSize: 14 }}>
            Projects
          </label>
          <input
            name="project_name"
            placeholder="Project Name"
            value={formData.project_name}
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />
          <input
            name="project_description"
            placeholder="Project Description"
            value={formData.project_description}
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />
          <label style={{ display: "block", marginTop: 8, marginBottom: 6, color: "#333", fontSize: 14 }}>
            Upload Resume (.txt or .pdf)
          </label>
          <input
            name="resume_file"
            type="file"
            accept=".txt,.pdf"
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />
          <button type="submit" className="btn-primary" style={{ marginTop: 12 }} disabled={loading}>
            {loading ? "Creating..." : "Create Freelancer Profile"}
          </button>
        </form>
      </div>
    </div>
  );
};

export default FreelancerForm;
